// The data of the create designer (app/(app)/(create)): registry/config.ts,
// registry/styles.tsx, the bases, base colors, themes and fonts, the icons
// of the IconPlaceholders, generated by gen/create.tsx.

//go:embed data/create/config.json
var createConfigJSON []byte

//go:embed data/create/font-classes.json
var createFontClassesJSON []byte

type cssVarPairs [][2]string

func (p cssVarPairs) get(name string) string {
	for _, kv := range p {
		if kv[0] == name {
			return kv[1]
		}
	}
	return ""
}

type createColor struct {
	Name    string                 `json:"name"`
	Title   string                 `json:"title"`
	CSSVars map[string]cssVarPairs `json:"cssVars"`
}

type createOption struct {
	Value string `json:"value"`
	Label string `json:"label"`
}

type createFont struct {
	Name            string `json:"name"`
	Title           string `json:"title"`
	Type            string `json:"type"`
	Family          string `json:"family"`
	PreviewVariable string `json:"previewVariable"`
}

// fontFamily is the font option's style.fontFamily (lib/fonts.ts).
func (f createFont) fontFamily() string { return "var(" + f.PreviewVariable + "), " + f.Family }

type createData struct {
	Default map[string]any `json:"default"`
	Styles  []struct {
		Name        string `json:"name"`
		Title       string `json:"title"`
		Description string `json:"description"`
		Icon        string `json:"icon"`
	} `json:"styles"`
	Bases []struct {
		Name        string `json:"name"`
		Title       string `json:"title"`
		Description string `json:"description"`
		Logo        string `json:"logo"`
	} `json:"bases"`
	BaseColors    []createColor `json:"baseColors"`
	Themes        []createColor `json:"themes"`
	IconLibraries []struct {
		Name  string `json:"name"`
		Title string `json:"title"`
	} `json:"iconLibraries"`
	MenuAccents []createOption `json:"menuAccents"`
	MenuColors  []createOption `json:"menuColors"`
	Radii       []struct {
		Name  string `json:"name"`
		Label string `json:"label"`
		Value string `json:"value"`
	} `json:"radii"`
	Fonts     []createFont                 `json:"fonts"`
	Presets   []map[string]any             `json:"presets"`
	Icons     map[string]map[string]string `json:"icons"`
	QRConnect string                       `json:"qrConnect"`
	// Hugeicons are the create components' hugeicons; IconLibraryLogos the
	// icon library picker's logos.
	Hugeicons        map[string]string `json:"hugeicons"`
	IconLibraryLogos map[string]string `json:"iconLibraryLogos"`
	// Templates and TurborepoLogo are project-form.tsx's.
	Templates []struct {
		Value string `json:"value"`
		Title string `json:"title"`
		Logo  string `json:"logo"`
	} `json:"templates"`
	TurborepoLogo string `json:"turborepoLogo"`

	fontClasses []string
}

var createDataOnce = sync.OnceValue(func() *createData {
	d := &createData{}
	if err := json.Unmarshal(createConfigJSON, d); err != nil {
		panic("create: config.json: " + err.Error())
	}
	_ = json.Unmarshal(createFontClassesJSON, &d.fontClasses)
	return d
})

func (d *createData) baseColor(name string) *createColor {
	for i := range d.BaseColors {
		if d.BaseColors[i].Name == name {
			return &d.BaseColors[i]
		}
	}
	return nil
}

func (d *createData) theme(name string) *createColor {
	for i := range d.Themes {
		if d.Themes[i].Name == name {
			return &d.Themes[i]
		}
	}
	return nil
}

func (d *createData) font(name string) (createFont, bool) {
	for _, f := range d.Fonts {
		if f.Name == name {
			return f, true
		}
	}
	return createFont{}, false
}

// isBaseColor reports whether a theme is one of the base colors.
func (d *createData) isBaseColor(name string) bool { return d.baseColor(name) != nil }

// themesForBaseColor is getThemesForBaseColor.
func (d *createData) themesForBaseColor(baseColor string) []createColor {
	var out []createColor
	for _, t := range d.Themes {
		if t.Name == baseColor || !d.isBaseColor(t.Name) {
			out = append(out, t)
		}
	}
	return out
}

// --- design system params (lib/search-params.ts) ---

// designSystem is the design system part of the search params.
type designSystem struct {
	Base, Item, Style, BaseColor, Theme, ChartColor, IconLibrary string
	Font, FontHeading, Radius, MenuAccent, MenuColor             string
	Pointer, RTL                                                 bool
}

func defaultDesignSystem() designSystem {
	return designSystem{
		Base: "base", Item: "preview-02", Style: "nova", BaseColor: "neutral", Theme: "neutral",
		ChartColor: "neutral", IconLibrary: "lucide", Font: "inter", FontHeading: "inherit",
		Radius: "default", MenuAccent: "subtle", MenuColor: "default",
	}
}

// The preset code fields (packages/registry/src/preset/preset.ts), v2.
var presetFields = []struct {
	key    string
	values []string
	bits   int
}{
	{"menuColor", []string{"default", "inverted", "default-translucent", "inverted-translucent"}, 3},
	{"menuAccent", []string{"subtle", "bold"}, 3},
	{"radius", []string{"default", "none", "small", "medium", "large"}, 4},
	{"font", presetFonts, 6},
	{"iconLibrary", []string{"lucide", "hugeicons", "tabler", "phosphor", "remixicon"}, 6},
	{"theme", presetThemes, 6},
	{"baseColor", []string{"neutral", "stone", "zinc", "gray", "mauve", "olive", "mist", "taupe"}, 6},
	{"style", []string{"nova", "vega", "maia", "lyra", "mira", "luma", "sera", "rhea"}, 6},
	{"chartColor", presetThemes, 6},
	{"fontHeading", append([]string{"inherit"}, presetFonts...), 5},
}

var presetThemes = []string{"neutral", "stone", "zinc", "gray", "amber", "blue", "cyan", "emerald", "fuchsia", "green", "indigo", "lime", "orange", "pink", "purple", "red", "rose", "sky", "teal", "violet", "yellow", "mauve", "olive", "mist", "taupe"}

var presetFonts = []string{"inter", "noto-sans", "nunito-sans", "figtree", "roboto", "raleway", "dm-sans", "public-sans", "outfit", "jetbrains-mono", "geist", "geist-mono", "lora", "merriweather", "playfair-display", "noto-serif", "roboto-slab", "oxanium", "manrope", "space-grotesk", "montserrat", "ibm-plex-sans", "source-sans-3", "instrument-sans", "eb-garamond", "instrument-serif"}

func (ds *designSystem) field(key string) *string {
	switch key {
	case "base":
		return &ds.Base
	case "item":
		return &ds.Item
	case "style":
		return &ds.Style
	case "baseColor":
		return &ds.BaseColor
	case "theme":
		return &ds.Theme
	case "chartColor":
		return &ds.ChartColor
	case "iconLibrary":
		return &ds.IconLibrary
	case "font":
		return &ds.Font
	case "fontHeading":
		return &ds.FontHeading
	case "radius":
		return &ds.Radius
	case "menuAccent":
		return &ds.MenuAccent
	case "menuColor":
		return &ds.MenuColor
	}
	return nil
}

const base62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

// presetCode is getPresetCode (encodePreset, always a "b" code).
func (ds designSystem) presetCode() string {
	bits := 0.0
	offset := 0
	for _, f := range presetFields {
		v := *ds.field(f.key)
		idx := 0
		for i, x := range f.values {
			if x == v {
				idx = i
			}
		}
		bits += float64(idx) * math.Pow(2, float64(offset))
		offset += f.bits
	}
	n := int64(bits)
	if n == 0 {
		return "b0"
	}
	var s []byte
	for n > 0 {
		s = append([]byte{base62[n%62]}, s...)
		n /= 62
	}
	return "b" + string(s)
}

// decodePreset decodes a preset code ("a" or "b") into ds.
func (ds *designSystem) decodePreset(code string) bool {
	if len(code) < 2 || len(code) > 10 || (code[0] != 'a' && code[0] != 'b') {
		return false
	}
	bits := 0.0
	for i := 1; i < len(code); i++ {
		idx := strings.IndexByte(base62, code[i])
		if idx < 0 {
			return false
		}
		bits = bits*62 + float64(idx)
	}
	fields := presetFields
	if code[0] == 'a' {
		fields = presetFields[:8]
	}
	offset := 0
	for _, f := range fields {
		idx := int(math.Mod(math.Floor(bits/math.Pow(2, float64(offset))), math.Pow(2, float64(f.bits))))
		v := f.values[0]
		if idx < len(f.values) {
			v = f.values[idx]
		}
		*ds.field(f.key) = v
		offset += f.bits
	}
	if code[0] == 'a' {
		ds.FontHeading = "inherit"
		// V1_CHART_COLOR_MAP: base-color themes borrowed colored charts.
		ds.ChartColor = ds.Theme
		if c, ok := map[string]string{"neutral": "blue", "stone": "lime", "zinc": "amber", "mauve": "emerald", "olive": "violet", "mist": "rose", "taupe": "cyan"}[ds.Theme]; ok {
			ds.ChartColor = c
		}
	}
	return true
}

// designSystemFromQuery reads the design system params as
// useDesignSystemSearchParams does (resolvePresetParams): a valid preset code
// gives the design system values (only fontHeading and chartColor can be
// overridden next to it), otherwise the individual params do; then
// normalizeDesignSystemParams.
func designSystemFromQuery(q url.Values) designSystem {
	d := createDataOnce()
	ds := defaultDesignSystem()
	valid := map[string]func(string) bool{
		"style": func(v string) bool {
			for _, s := range d.Styles {
				if s.Name == v {
					return true
				}
			}
			return false
		},
		"baseColor":   func(v string) bool { return d.baseColor(v) != nil },
		"theme":       func(v string) bool { return d.theme(v) != nil },
		"chartColor":  func(v string) bool { return d.theme(v) != nil },
		"iconLibrary": func(v string) bool { _, ok := d.Icons[v]; return ok },
		"font":        func(v string) bool { _, ok := d.font(v); return ok },
		"fontHeading": func(v string) bool { _, ok := d.font(v); return ok || v == "inherit" },
		"radius": func(v string) bool {
			for _, r := range d.Radii {
				if r.Name == v {
					return true
				}
			}
			return false
		},
		"menuAccent": func(v string) bool { return v == "subtle" || v == "bold" },
		"menuColor": func(v string) bool {
			for _, m := range d.MenuColors {
				if m.Value == v {
					return true
				}
			}
			return false
		},
	}
	set := func(key string) {
		if v := q.Get(key); v != "" && valid[key](v) {
			*ds.field(key) = v
		}
	}
	if p := q.Get("preset"); p != "" && ds.decodePreset(p) {
		set("fontHeading")
		set("chartColor")
	} else {
		ds = defaultDesignSystem()
		for key := range valid {
			set(key)
		}
	}
	for _, b := range d.Bases {
		if q.Get("base") == b.Name {
			ds.Base = b.Name
		}
	}
	if v := q.Get("item"); v != "" {
		ds.Item = v
	}
	ds.Pointer = q.Get("pointer") == "true"
	ds.RTL = q.Get("rtl") == "true"
	ds.normalize()
	return ds
}

// normalize is normalizeDesignSystemParams.
func (ds *designSystem) normalize() {
	d := createDataOnce()
	if ds.FontHeading == ds.Font {
		ds.FontHeading = "inherit"
	}
	available := d.themesForBaseColor(ds.BaseColor)
	has := func(name string) bool {
		for _, t := range available {
			if t.Name == name {
				return true
			}
		}
		return false
	}
	if !has(ds.Theme) || !has(ds.ChartColor) {
		fallback := ds.BaseColor
		if len(available) > 0 {
			fallback = available[0].Name
		}
		if !has(ds.Theme) {
			ds.Theme = fallback
		}
		if !has(ds.ChartColor) {
			ds.ChartColor = fallback
		}
	}
	if ds.MenuAccent == "bold" && strings.HasSuffix(ds.MenuColor, "translucent") {
		ds.MenuAccent = "subtle"
	}
}

// effectiveRadius is the radius the preview applies (lyra has none).
func (ds designSystem) effectiveRadius() string {
	if ds.Style == "lyra" || ds.Style == "sera" {
		return "none"
	}
	if ds.Style == "rhea" && ds.Radius == "large" {
		return "default"
	}
	return ds.Radius
}

// themeCSS is the design-system-theme-vars stylesheet of the preview
// (DesignSystemProvider: buildRegistryTheme, buildThemeCssText).
func (ds designSystem) themeCSS() string {
	d := createDataOnce()
	bc, th := d.baseColor(ds.BaseColor), d.theme(ds.Theme)
	if bc == nil || th == nil {
		return ""
	}
	merge := func(mode string) cssVarPairs {
		var out cssVarPairs
		set := func(k, v string) {
			for i := range out {
				if out[i][0] == k {
					out[i][1] = v
					return
				}
			}
			out = append(out, [2]string{k, v})
		}
		for _, kv := range bc.CSSVars[mode] {
			set(kv[0], kv[1])
		}
		for _, kv := range th.CSSVars[mode] {
			set(kv[0], kv[1])
		}
		if chart := d.theme(ds.ChartColor); chart != nil {
			for i := 1; i <= 5; i++ {
				k := "chart-" + string(rune('0'+i))
				if v := chart.CSSVars[mode].get(k); v != "" {
					set(k, v)
				}
			}
		}
		if ds.MenuAccent == "bold" {
			set("accent", out.get("primary"))
			set("accent-foreground", out.get("primary-foreground"))
		}
		if r := ds.effectiveRadius(); mode == "light" && r != "default" {
			for _, x := range d.Radii {
				if x.Name == r && x.Value != "" {
					set("radius", x.Value)
				}
			}
		}
		return out
	}
	rule := func(sel string, vars cssVarPairs) string {
		var b strings.Builder
		for _, kv := range vars {
			if kv[1] != "" {
				b.WriteString("  --" + kv[0] + ": " + kv[1] + ";\n")
			}
		}
		if b.Len() == 0 {
			return sel + " {}\n"
		}
		return sel + " {\n" + b.String() + "}\n"
	}
	css := rule(":root", merge("light")) + "\n" + rule(".dark", merge("dark"))
	if ds.Pointer {
		css += "\n@layer base {\n  button:not(:disabled), [role=\"button\"]:not(:disabled) {\n    cursor: pointer;\n  }\n}\n"
	}
	return css
}

// fontFamilies returns the --font-sans and --font-heading values.
func (ds designSystem) fontFamilies() (sans, heading string) {
	d := createDataOnce()
	f, ok := d.font(ds.Font)
	if ok {
		sans, heading = f.fontFamily(), f.fontFamily()
	}
	if ds.FontHeading != "inherit" && ds.FontHeading != ds.Font {
		if hf, ok := d.font(ds.FontHeading); ok {
			heading = hf.fontFamily()
		}
	}
	return sans, heading
}

// --- icons (components/icon-placeholder.tsx) ---

type iconLibraryKey struct{}

// withIconLibrary renders children with the given icon library.
func withIconLibrary(lib string, children ...any) h.Node {
	return h.WithValue(iconLibraryKey{}, lib, children...)
}

// placeholderIcon is IconPlaceholder: one icon name per library; the
// library comes from the enclosing withIconLibrary (lucide by default).
type placeholderIcon struct {
	names map[string]string
	class string
	attrs []string
}

// ip is <IconPlaceholder lucide tabler hugeicons phosphor remixicon
// className {...attrs} />: names is "lucide|tabler|hugeicons|phosphor|remixicon",
// attrs are name, value pairs.
func ip(names, class string, attrs ...string) h.Node {
	n := strings.Split(names, "|")
	for len(n) < 5 {
		n = append(n, "")
	}
	return &placeholderIcon{
		names: map[string]string{"lucide": n[0], "tabler": n[1], "hugeicons": n[2], "phosphor": n[3], "remixicon": n[4]},
		class: class, attrs: attrs,
	}
}

func (p *placeholderIcon) Render(w io.Writer) error {
	lib := "lucide"
	if v, ok := h.Lookup(w, iconLibraryKey{}); ok {
		lib = v.(string)
	}
	return h.UnsafeHTML(iconMarkup(lib, p.names[lib], p.class, p.attrs...)).Render(w)
}

// iconMarkup renders a generated icon with a class and extra attributes.
func iconMarkup(lib, name, class string, attrs ...string) string {
	svg := createDataOnce().Icons[lib][name]
	if svg == "" {
		return ""
	}
	if class == "" {
		svg = strings.Replace(svg, " __CLS__", "", 1)
		svg = strings.Replace(svg, ` class="__CLS__"`, "", 1)
	} else {
		svg = strings.Replace(svg, "__CLS__", html.EscapeString(class), 1)
	}
	if len(attrs) > 0 {
		var b strings.Builder
		for i := 0; i+1 < len(attrs); i += 2 {
			b.WriteString(" " + attrs[i] + `="` + html.EscapeString(attrs[i+1]) + `"`)
		}
		svg = strings.Replace(svg, "<svg", "<svg"+b.String(), 1)
	}
	return svg
}
